## 이슈넘버
#731 

## 소스코드
```cpp
#include <iostream>
#include <queue>

int main()
{
    int N, K, answer = 0;
    int start, end, pre, tmp;

    std::cin >> N >> K >> start;


    pre = start;
    std::priority_queue<int> pq;

    for (int i=1; i<N; ++i)
    {
        std::cin >> tmp;
        pq.push(tmp- pre-1);
        pre = tmp;
    }

    end = pre;
    answer = end+1 - start; // 전체 시간 (마지막으로 나간 시간 - 처음 들어온 시간)

    while (--K)
    {
        answer -= pq.top();
        pq.pop();
    }

    std::cout << answer;

    return 0;
}
```

